import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();int[] counts={0,1,0,0,2,10,4,40,92,352};for(int n=1;n<=9;n++){List<List<String>> boards=s.solveNQueens(n);if(boards.size()!=counts[n])throw new AssertionError(n);Set<String> unique=new HashSet<>();for(List<String> b:boards){if(b.size()!=n||!unique.add(b.toString()))throw new AssertionError();int[] c=new int[n];for(int r=0;r<n;r++){String row=b.get(r);if(row.length()!=n||row.chars().filter(x->x=='Q').count()!=1)throw new AssertionError();c[r]=row.indexOf('Q');for(int q=0;q<r;q++)if(c[q]==c[r]||Math.abs(c[q]-c[r])==r-q)throw new AssertionError();}}}System.out.println("Samples and original edge/reference checks passed");}}